"""Read the catalog file and look books up."""

FIELDS = ("isbn", "title", "author", "year", "price_cents")


def load_catalog(path):
    """Every book in the tab-separated file at path, as a dict with FIELDS as keys."""
    books = []
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            line = line.rstrip("\n")
            if not line.strip() or line.lstrip().startswith("#"):
                continue
            book = dict(zip(FIELDS, line.split("\t"), strict=True))
            book["year"] = int(book["year"])
            book["price_cents"] = int(book["price_cents"])
            books.append(book)
    return books


def find(books, title=None, author=None, *, year=None):
    """The books whose title and author contain the given text, ignoring case, and whose year matches."""
    found = []
    for book in books:
        if title and title.casefold() not in book["title"].casefold():
            continue
        if author and author.casefold() not in book["author"].casefold():
            continue
        if year is not None and book["year"] != year:
            continue
        found.append(book)
    return found


def search(books, text, *, year=None, fields=("title", "author")):
    """The books where every word of text appears in one of fields, ignoring case, and whose year matches."""
    words = text.casefold().split()
    found = []
    for book in books:
        if year is not None and book["year"] != year:
            continue
        haystacks = [book[field].casefold() for field in fields]
        if all(any(word in haystack for haystack in haystacks) for word in words):
            found.append(book)
    return found
